INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37366','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo rural común del siglo XVI ejecutado en mampostería granítica de la comarca de Vitigudino que cuenta con una nave única rematada en un presbiterio de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37373','iglesia','Iglesia Parroquial de San Pedro Apóstol','Edificio monumental del siglo XVI proyectado en el Campo de Yeltes enteramente en sillería granítica que destaca por su fachada renacentista herreriana y una espaciosa nave única con un presbiterio de gran solidez formal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37378','monumento','Núcleos de población de Zamarra','El término municipal incluye los siguientes núcleos de población: Villarejo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37378','iglesia','Iglesia Parroquial de la Asunción','Templo rural común del siglo XVI levantado con paramentos de mampostería granítica del Campo de Agadones que cuenta con una nave de tramos regulares rematada en un presbiterio cupulado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48001','iglesia','Iglesia de Nuestra Señora de la Asunción','Templo gótico-renacentista del siglo XVI edificado sobre un antiguo cimiento románico que destaca por su portada clasicista labrada en granito berroqueño local y una robusta torre-campanario que sirvió de hito defensivo en la frontera lusa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48001','palacio','Palacio de los de los Marqueses de Alcañices','Edificio civil de traza renacentista profundamente reformado en el siglo XVIII que destaca por sus severos muros de mampostería de pizarra rústica y por ser el escenario histórico donde se firmó el trascendental Tratado de Alcañices en 1297.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90675','iglesia','Iglesia Parroquial de la Asunción','Templo de filiación renacentista castellana del siglo XVI edificado con muros de mampostería caliza y ladrillo en la comarca de la Tierra del Vino que destaca por su ábside poligonal protegido por contrafuertes y una recia torre campanario adosada a los pies.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49019','iglesia','Iglesia Parroquial de Santa Marina','Templo renacentista castellano ordinario del siglo XVI levantado con cajones de mampostería local caliza y ladrillo que cuenta con una nave de tramos regulares y una espadaña de dos vanos con pináculos decorativos sobre los pies del edificio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49023','monumento','Núcleos de población de Bermillo de Sayago','El término municipal incluye los siguientes núcleos de población: Fadón, Bermillo, Piñuel, Torrefrades, Palazuelo de Sayago, Villamor de Cadozos y Gáname.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49023','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo del siglo XVI levantado en mampostería de granito berroqueño sayagués que destaca por su recia torre campanario de tres cuerpos decrecientes y un presbiterio protegido por contrafuertes exteriores que cobija una bóveda de arista barroca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49036','iglesia','Iglesia Parroquial de San Pedro','Monumental templo gótico-renacentista del siglo XVI alzado en la comarca de Alba enteramente en sillería granítica que destaca por su imponente torre campanario de tres cuerpos, sus portadas platerescas de fina talla y un presbiterio de gran solidez formal, sirviendo la localidad como foco etnográfico por sus célebres bordados tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49042','iglesia','Iglesia Parroquial de Santa María de la Asunción','Templo renacentista castellano común del siglo XVI levantado con cajones de mampostería caliza y ladrillo que cuenta con una nave de tramos regulares y una espadaña de dos vanos con pináculos decorativos sobre los pies del edificio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49061','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo rural común del siglo XVI levantado en la comarca de la Tierra del Vino con muros de mampostería caliza y sillería en las esquinas que presenta una nave única compartimentada por sencillos arcos de medio punto y una sobria espadaña frontal de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49063','iglesia','Iglesia Parroquial de San Martín','Edificación renacentista castellana del siglo XVI ejecutada en la comarca de Tábara mediante cajones de mampostería vista y verdugadas de ladrillo que presenta un ábside poligonal protegido por contrafuertes y una recia torre campanario adosada a los pies de la nave única.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49078','iglesia','Iglesia Parroquial de San Pedro','Pequeña edificación rural ordinaria del siglo XVI ejecutada con mampostería local encalada en el Valle de Valverde que presenta una estructura de nave única rematada por una modesta espadaña de sillería rústica situada a los pies del templo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49086','iglesia','Iglesia Parroquial de San Juan Bautista','Templo rural común de traza renacentista castellana del siglo XVI ejecutado mediante cajones de mampostería caliza y ladrillo en la comarca de la Tierra del Pan que presenta una nave única rematada por una espadaña de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49093','iglesia','Iglesia Parroquial de la Asunción','Templo del siglo XVI levantado en la comarca de la Guareña que destaca por su portada renacentista de líneas clasicistas herrerianas y un interior de amplias dimensiones con un presbiterio cubierto por una bóveda de arista barroca de notable factura formal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49096','iglesia','Iglesia Parroquial de Nuestra Señora de la Concepción','Templo renacentista del siglo XVI edificado en la comarca de la Tierra del Vino mediante sillares de piedra caliza que destaca por su portada clasicista moldurada, un coro alto sobre canecillos de madera y una esbelta espadaña barroca de tres cuerpos decrecientes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49098','monumento','Núcleos de población de Losacino','El término municipal incluye los siguientes núcleos de población: Castillo de Alba, Muga de Alba y Vide de Alba.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49098','monumento','Castillo de Alba','Fortaleza medieval defensiva erigida en el siglo XII sobre un escarpado cerro calizo en las proximidades del río Aliste de la que subsisten imponentes lienzos de muralla de mampostería y los restos consolidados de su torre del homenaje poligonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49098','iglesia','Iglesia Parroquial de San Juan Bautista (Losacino)','Edificación del siglo XVI construida en mampostería rústica y pizarra que presenta una nave de tramos regulares rematada en un presbiterio de planta cuadrada cubierto por una bóveda de arista barroca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49103','monumento','Núcleos de población de Madridanos','El término municipal incluye los siguientes núcleos de población: Bamba.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49103','iglesia','Iglesia Parroquial de San Lorenzo','Templo de filiación renacentista castellana común del siglo XVI levantado en la Tierra del Vino con muros de mampostería caliza y sillería en las esquinas que presenta una nave única rematada por una espadaña de dos vanos con pináculos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49109','monumento','Yacimiento Arqueológico de El Pesadero','Destacado poblado astur y posterior asentamiento romano perfectamente musealizado que conserva estructuras habitacionales excavadas y muros de piedra rústica que atestiguan la ocupación milenaria de los Valles de Benavente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49109','iglesia','Iglesia Parroquial de San Vicente','Templo renacentista del siglo XVI construido en mampostería caliza y ladrillo que presenta una portada clasicista moldurada de líneas muy sobrias y una nave única rematada por una espadaña de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49118','iglesia','Iglesia Parroquial de San Martín','Pequeña edificación rural ordinaria del siglo XVI ejecutada con mampostería local encalada en la Polvorosa que presenta una estructura de nave única rematada por una modesta espadaña de sillería rústica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49129','iglesia','Iglesia Parroquial de San Juan Bautista','Templo herreriano de gran envergadura iniciado en el siglo XVI que presenta una imponente fachada de sillería de orden neoclásico clasicista y un espacioso interior de tres naves con grandiosas bóvedas de arista vinculadas a los grandes talleres canteros toresanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49137','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo de filiación renacentista castellana común del siglo XVI levantado en el Valle de Valverde con','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49138','monumento','Núcleos de población de Olmillos de Castro','El término municipal incluye los siguientes núcleos de población: Marquiz de Alba, Navianos de Alba y San Martín de Tábara.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49138','iglesia','Iglesia Parroquial de San Martín','Inmueble parroquial de traza renacentista castellana modificado en el siglo XVIII mediante el uso de materiales locales como la mampostería de pizarra y el ladrillo visto, caracterizado por una pequeña espadaña lateral de dos vanos decrecientes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49160','iglesia','Iglesia Parroquial de San Miguel','Sencillo edificio parroquial mudéjar modificado en el siglo XVIII mediante el uso de materiales locales como la mampostería encalada y el ladrillo visto, caracterizado por una pequeña espadaña de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49173','monumento','Núcleos de población de Rábano de Aliste','El término municipal incluye los siguientes núcleos de población: Alcorcillo, Sejas de Aliste, Tola y San Mamed.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49173','iglesia','Iglesia de San Lorenzo (Sejas de Aliste)','Monumental templo del siglo XVI que presenta muros de mampostería de pizarra rústica y granito característicos de la arquitectura alistana, albergando una magnífica techumbre de madera policromada con lacerías de lazo morisco de notable factura formal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49176','iglesia','Iglesia Parroquial de Santa María','Templo de filiación renacentista del siglo XVI levantado con sillarejos de pizarra rústica y mampostería vista de la comarca de Aliste que presenta un ábside poligonal y una recia torre campanario exenta que sirve de eje para las fiestas etnográficas de carantoñas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49179','monumento','Núcleos de población de Robleda-Cervantes','El término municipal incluye los siguientes núcleos de población: Barrio de la Gándara, Cervantes, Ferreros, Paramio, Sampil, San Juan de la Cuesta, Triufé y Valdespino.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49179','iglesia','Iglesia Parroquial de San Juan Bautista (San Juan de la Cuesta)','Templo gótico-renacentista del siglo XVI edificado con paramentos de mampostería de pizarra rústica y piedra que destaca por su recia torre campanario adosada a los pies y por un presbiterio que conserva una armadura de madera restaurada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49183','iglesia','Iglesia Parroquial de San Miguel Arcángel','Templo rural ordinario del siglo XVI ejecutado en mampostería granítica sayaguesa que presenta un sobrio interior de nave única compartimentado por arcos fajones de medio punto y una espadaña de dos vanos con tejadillo moldurado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49206','monumento','Núcleos de población de Santibáñez de Vidriales','El término municipal incluye los siguientes núcleos de población: Bercianos de Vidriales, Rosinos de Vidriales, San Pedro de la Viña y Tardemezar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49206','monumento','Campamento Romano de Petavonium (Rosinos)','Impresionante complejo militar y yacimiento arqueológico del siglo I d.C. perfectamente musealizado que conserva los cimientos de los barracones, las termas y la reconstrucción de las monumentales puertas de acceso de sillería granítica pertenecientes a la Legio X Gemina.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49206','iglesia','Iglesia Parroquial de San Juan Bautista','Templo renacentista del siglo XVI construido en mampostería caliza y ladrillo que presenta una portada clasicista moldurada de líneas muy sobrias y una nave única rematada por una espadaña de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49214','iglesia','Iglesia Parroquial de Santa María y su Torre Románica','Espectacular fábrica de origen mozárabe del siglo X reedificada en estilo románico en el siglo XII, declarada monumento nacional, que destaca a nivel mundial por albergar la monumental torre del antiguo monasterio tabular donde se iluminaron los célebres Beatos medievales miniados de traza hispanomusulmana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49225','iglesia','Iglesia Parroquial de San Pedro','Sencillo edificio del siglo XVI levantado con cajones de mampostería encalada en la comarca de Sanabria-Carballeda que presenta una modesta espadaña de sillería granítica situada a los pies de la nave única de tramos regulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49232','iglesia','Iglesia Parroquial de San Pedro','Sencillo edificio del siglo XVI levantado con cajones de mampostería encalada en la comarca de la Tierra de Campos que presenta una modesta espadaña de sillería granítica situada a los pies de la nave única de tramos regulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90676','monumento','Núcleos de población de Beade','El término municipal incluye los siguientes núcleos de población: As Regadas y San Amaro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90676','iglesia','Iglesia de Santa María de Beade','Extraordinario templo de la Orden de San Juan de Jerusalén reedificado en el siglo XVI en estilo renacentista que presenta una fachada clasicista rematada por una imponente torre-campanario y un interior de tres naves con cubiertas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90676','monumento','Vía Crucis de Beade','Calvario monumental barroco del siglo XVIII considerado uno de los más completos de Galicia al estar integrado por catorce estaciones exentas labradas en sillería granítica con relieves figurativos detallados de la Pasión.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90676','ermita','Ermita de San Roque','Modesta construcción religiosa del siglo XVII edificada con mampostería granítica que cuenta con una portada de arco de medio punto, espadaña de un solo vano y un retablo barroco de tipo cajón en su cabecera cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32026','monumento','Núcleos de población de Coles','El término municipal incluye los siguientes núcleos de población: Barra, Cambeo, Ferreiros, Melias y Vilariño.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32026','palacio','Pazo de Fontao','Casona solariega barroca del siglo XVIII edificada con aparejo de sillería granítica que destaca por su fachada monumental con tres grandes escudos de armas familiares, amplias balconadas de forja gallega y una escalinata de piedra noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32026','iglesia','Iglesia de San Miguel de Melias','Templo de fábrica barroca del siglo XVIII que conserva elementos estructurales de su origen medieval y exhibe una esbelta torre-campanario exenta de tres cuerpos rematada por un cupulino de cantería vista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32026','iglesia','Iglesia de San Juan de Barra','Edificación románica rural del siglo XII que preserva su nave única original con saeteras abocinadas, una portada occidental de arquivoltas lisas y una valiosa serie de canecillos historiados bajo el alero del tejado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32040','monumento','Núcleos de población de Leiro','El término municipal incluye los siguientes núcleos de población: Berán, Lebosende, Orega, San Clodio y Serantes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32040','iglesia','Monasterio de San Clodio','Cenobio medieval de la Orden del Císter fundado en el siglo XII que conserva una magnífica iglesia románica con fachada de tres arcos apuntados, un espectacular rosetón calado de sillería granítica gálica y dos majestuosos claustros clasicistas y barrocos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32040','iglesia','Iglesia de San Tomé de Serantes','Joya del románico rural de finales del siglo XII que destaca por su ábside semicircular perfecto con columnas adosadas, su portada occidental de tres arquivoltas profusamente decoradas con motivos vegetales y una rica serie de canecillos historiados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32040','palacio','Pazo de Casanova','Conjunto palaciego señorial del siglo XVIII vinculado a la producción vitivinícola del Ribeiro que posee un portalón heráldico con los blasones familiares, una solaina orientada a los bancales de viñedos y una capilla barroca privada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32040','monumento','Puente Medieval de Leiro','Estructura civil de arquerías ojivales erigida en sillería de granito berroqueño que salva el cauce del río Avia y conserva los tajamares triangulares diseñados para resistir las crecidas estacionales del río.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32060','monumento','Núcleos de población de Petín','El término municipal incluye los siguientes núcleos de población: Carballal, Mones, Santoalla do Monte y Freixido.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32060','monumento','Puente de la Cigarrosa','Monumental estructura civil de origen romano construida para dar continuidad a la Vía Nova sobre el río Sil que fue reformada en el siglo XVI mediante grandes arcos apuntados y de medio punto ejecutados en aparejo de sillería granítica y pizarra rústica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32060','iglesia','Iglesia de Santiago de Petín','Edificación religiosa del siglo XVIII adscrita al barroco rural que destaca por su fachada simétrica de sillería regular con portada de arco de medio punto flanqueada por pilastras molduradas y una esbelta espadaña de doble vano con pináculos barrocos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32060','ermita','Ermita de San Roque','Modesto oratorio del siglo XVII edificado con mampostería granítica concertada que presenta una planta rectangular con cubierta a dos aguas de losas de pizarra local, portada adintelada sobria y un retablo de madera de tipo cajón en su cabecera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32069','monumento','Núcleos de población de Ribadavia','El término municipal incluye los siguientes núcleos de población: Francelos, San Cristovo, Santo André y Ventosela.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32069','monumento','Castillo de los Condes de Ribadavia','Imponente fortaleza medieval del siglo XIV que domina la confluencia de los ríos Avia y Miño con sus extensas murallas de sillería granítica berroqueña, su gran patio de armas, sus torres de defensa cilíndricas y las necrópolis altomedievales excavadas en la roca natural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32069','monumento','Barrio Judío de Ribadavia','Conjunto histórico-artístico medieval excelentemente conservado que destaca por su trazado urbano intrincado de calles empedradas con losas graníticas, sus casas porticadas con arquerías de sillería y sus bodegas medievales destinadas a la producción tradicional del vino Ribeiro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32069','iglesia','Iglesia de Santiago','Joya del románico urbano de finales del siglo XII que resalta por su fachada occidental con una magnífica portada de arquivoltas historiadas, su ábside semicircular perfecto decorado con arquerías ciegas y una estatua sedente de Santiago Apóstol en piedra noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32069','iglesia','Capilla de San Xes de Francelos','Singular edificación prerrománica del siglo IX reedificada que conserva valiosos relieves decorativos de filiación visigótica y mozárabe, un arco triunfal de herradura apoyado sobre columnas romanas reutilizadas y una ventana calada de celosía pétrea.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32069','iglesia','Monasterio de Santo Domingo','Cenobio de la Orden de Predicadores de los siglos XIII y XIV que constituye un ejemplo señero del gótico mendicante gallego con su iglesia abacial de tres naves, sus ábsides poligonales','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32071','monumento','Núcleos de población de Riós','El término municipal incluye los siguientes núcleos de población: Castrelo de Cima, Castrelo de Abaixo, Fumaces, Progo y Vilardevós.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32071','iglesia','Iglesia de Santa María de Riós','Templo parroquial del siglo XVIII inscrito en el estilo barroco rural de la raya fronteriza que resalta por su fachada neoclásica exenta de ornamentación pesada, una torre-campanario central rematada por un cupulino de cantería y un retablo mayor churrigueresco de rica talla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32071','monumento','Caserío de Fumaces','Conjunto arquitectónico de mampostería tradicional y losas de pizarra rústica vinculado al Camino de Santiago Sanabrés que conserva antiguas posadas de arriería con portadas adinteladas y hórreos tradicionales del tipo fisterrán.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32071','monumento','Cruceiro de Castrelo de Cima','Monumento religioso y etnográfico del siglo XIX labrado en granito del país que presenta un pedestal moldurado sobre tres gradas, fuste estriado y una cruz superior ornamentada con las figuras de la Piedad y Cristo Crucificado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32079','monumento','Núcleos de población de Taboadela','El término municipal incluye los siguientes núcleos de población: Mesón de Calvos, O Corgo, Santiago da Rabeda, Soutomaior y Torán.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32079','monumento','Torre de Torán','Vestigio fortificado de una antigua casa torre medieval del siglo XIV que se eleva sobre un afloramiento rocoso conservando sus potentes muros perimetrales de sillería granítica berroqueña y estrechas saeteras de función defensiva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32079','iglesia','Iglesia de Santiago da Rabeda','Edificación románica rural de finales del siglo XII que preserva su nave única original de sillería isódoma perfecta, una portada occidental de arquivoltas lisas y una valiosa serie de canecillos geométricos bajo el alero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32079','palacio','Pazo de Mezquita','Gran casona solariega del siglo XVII construida en aparejo de cantería regular que exhibe un portalón de acceso flanqueado por pináculos heráldicos, amplias solainas sobre columnas graníticas y una capilla barroca privada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90677','monumento','Núcleos de población de Barro','El término municipal incluye los siguientes núcleos de población: Agudelo, Baliñas, Curro, Perdecanai, Portela y Valiñas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90677','iglesia','Iglesia de San Martiño de Agudelo','Edificación románica de finales del siglo XII modificada en el barroco que preserva su cabecera rectangular primitiva, capiteles decorados con motivos vegetales esquemáticos y una hermosa portada occidental que destaca por sus arquivoltas molduradas sobre columnas exentas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90677','monumento','Conjunto Hidráulico de los Molinos de Barosa','Agrupación de arquitectura tradicional e industrial menor que congrega catorce molinos harineros de agua construidos en mampostería granítica, alineados de forma escalonada aprovechando los saltos de agua y cascadas naturales del río Barosa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90677','palacio','Pazo de la Breca','Gran residencia solariega del siglo XVIII de planta rectangular que exhibe una fachada monumental barroca con amplias balconadas de forja gallega, un portalón de acceso adintelado con grandes blasones heráldicos labrados en piedra noble y un antiguo palomar circular exento.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36902','monumento','Núcleos de población de Cerdedo-Cotobade','El término municipal incluye los siguientes núcleos de población: Aguasantas, Carballedo, Cerdedo, Corredoira, Tenorio y Valongo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36902','iglesia','Monasterio de San Pedro de Tenorio','Antiguo cenobio benedictino de origen medieval profundamente reformado en el siglo XVIII que destaca por conservar su iglesia abacial de planta de cruz latina, una fachada clasicista barroca de sillería regular y un claustro bajo de gran pureza formal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36902','ermita','Puente y Ermita de San Antón de Pedre','Estructura civil medieval erigida en sillería de granito berroqueño con un gran arco apuntado que salva el río Lérez para dar continuidad al antiguo camino de arriería, flanqueada por una pequeña capilla popular con espadaña de un solo vano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36902','monumento','Eira de Hórreos de Pedre','Uno de los conjuntos etnográficos más espectaciores de Galicia que reúne una excepcional agrupación de hórreos tradicionales alineados sobre una plataforma rocosa comunal, construidos con pies de cantería y listones de madera de sabina o piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36902','iglesia','Iglesia de San Martín de Cerdedo','Templo parroquial barroco del siglo XVIII proyectado con elegante traza clasicista que exhibe una fachada monumental de cantería regular flanqueada por pilastras cajeadas, una esbelta torre-campanario y un retablo mayor dorado churrigueresco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36013','monumento','Núcleos de población de Sanxenxo','El término municipal incluye los siguientes núcleos de población: Adina, Arra, Bordóns, Dorrón, Noalla, Padriñán y Vilalonga.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36013','ermita','Ermita de Nuestra Señora de la Lanzada','Emblemático templo románico tardío del siglo XII edificado sobre un promontorio rocoso batido por el océano Atlántico que presenta una planta de nave única con ábside semicircular de sillería regular y capiteles lisos de proa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36013','palacio','Pazo de Quintáns (Noalla)','Conjunto palaciego señorial del siglo XVII de planta rectangular que exhibe una fachada monumental de sillería granítica gálica, grandes escudos heráldicos labrados, una solaina interior sobre robustos pilares y una capilla privada adosada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36013','iglesia','Iglesia de San Juan de Dorrón','Edificación de origen medieval reformada en época barroca que conserva de su antigua fábrica románica la estructura de su cabecera rectangular de sillería isódoma perfecta y una valiosa serie de canecillos geométricos bien labrados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36013','palacio','Pazo de Miraflores','Casona solariega barroca del siglo XVIII construida con aparejo granítico concertado que destaca por sus amplias solainas corridas, un portalón de acceso adintelado provisto de pináculos heráldicos y unos frondosos jardines perimetrales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36016','monumento','Núcleos de población de Vilagarcía de Arousa','El término municipal incluye los siguientes núcleos de población: Bamio, Carril, Fontecarmoa, Vilaxoán y Sobradelo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36016','iglesia','Pazo e Iglesia de Vista Alegre','Monumental conjunto arquitectónico barroco del siglo XVII catalogado como Bien de Interés Cultural que se compone de un gran palacio blasonado con torres almenadas unido mediante un arco-pasadizo elevado a un convento agustino.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36016','palacio','Pazo de O Rial','Gran residencia solariega del siglo XVII construida en aparejo de sillería granítica gálica perfectamente labrada que exhibe una fachada flanqueada por dos torres de planta cuadrada decoradas con pináculos heráldicos y balconadas de forja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36016','iglesia','Iglesia de San Martín de Sobrán (Vilaxoán)','Joya del románico de transición de finales del siglo XII que conserva una magnífica portada occidental con arquivoltas profundas labradas, capiteles historiados zoomorfos y un ábside semicircular perfecto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36016','monumento','Castro de Alobre','Yacimiento arqueológico de la Edad del Hierro y época romano-gala musealizado que preserva la estructura de su muralla perimetral de mampostería en seco junto a viviendas indígenas y piletas destinadas a la industria de salazón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27023','monumento','Núcleos de población de Guntín','El término municipal incluye los siguientes núcleos de población: Castelo de Pallares, Entrambasaugas, Ferreira de Pallares, Lousada, Piñeiras y Pradeda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27023','iglesia','Monasterio de Santa María de Ferreira de Pallares','Cenobio medieval de la Orden de San Benito declarado Monumento Nacional que conserva una monumental iglesia románica del siglo XII con ábside semicircular, una portada de arquivoltas profundas labradas y claustro gótico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27023','monumento','Torre de San Paio de de Pallares','Esbelta torre del homenaje exenta de planta cuadrada perteneciente a una fortaleza medieval del siglo XIV que se eleva con potentes muros de sillería granítica berroqueña y conserva sus saeteras defensivas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27023','palacio','Pazo de de de Bescansa','Gran casona hidalga del siglo XVIII de planta rectangular que exhibe una fachada monumental barroca con amplias balconadas de forja gallega y un portalón de acceso adintelado con grandes blasones heráldicos labrados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27051','monumento','Núcleos de población de Ribadeo','El término municipal incluye los siguientes núcleos de población: Arante, Cedofeita, Couxela, Ove, Rinlo, Santalla de Vilausende y Vilaframil.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27051','monumento','Torre de los Moreno','Monumental palacio modernista y ecléctico de principios del siglo XX proyectado con una innovadora estructura de hormigón que destaca por su suntuosa fachada decorada con azulejos, sus miradores acristalados y una esbelta cúpula neomudéjar sustentada por columnas de piedra noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27051','palacio','Aduana Vieja (Pazo de Ibáñez)','Actual palacio consistorial neoclásico de finales del siglo XVIII edificado en aparejo de sillería granítica gálica perfectamente labrada que exhibe una fachada monumental de líneas puras con soportales de arquerías de medio punto y balconadas de forja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27051','iglesia','Santuario de Nuestra Señora de las Virtudes (Arante)','Templo románico rural de finales del siglo XII estrechamente vinculado a las peregrinaciones del Camino del Norte que destaca por albergar en su interior un extraordinario conjunto de pinturas murales góticas del siglo XIV bien conservadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27051','iglesia','Capilla de la Atalaya','Modesto oratorio medieval fundado en el siglo XII emplazado estratégicamente sobre un acantilado que domina la ría que conserva muros de mampostería vista de cuarcita local, una portada de arco apuntado gótico y antiguos cañones de defensa costera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28013','monumento','Núcleos de población de Viveiro','El término municipal incluye los siguientes núcleos de población: Area, Celeiro, Covas, Galdo, Landrove, Magazos y Valcarría.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28013','monumento','Puerta de del Carlos V (Castelo da Ponte)','Monumental arco de triunfo plateresco del siglo XVI integrado en el antiguo recinto amurallado que destaca por su fachada de sillería granítica berroqueña decorada con los bustos y escudos heráldicos imperiales labrados en relieve.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28013','iglesia','Iglesia y Monasterio de de San Francisco','Magno templo del gótico mendicante de los siglos XIV y XV declarado Monumento Nacional que presenta una planta de cruz latina con un testero de tres ábsides poligonales cubiertos con bóveda de crucería y un bellísimo claustro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28013','iglesia','Iglesia de Santa María del Campo','Joya del románico urbano de finales del siglo XII que destaca por su ábside semicircular perfecto de sillería isódoma, su portada occidental de arquivoltas profundas molduradas sobre capiteles historiados y una esbelta torre-campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28013','monumento','Puente Mayor de del de Viveiro (Ponte Maior)','Monumental estructura civil de origen medieval reformada en el siglo XVIII que salva el estuario de la ría mediante doce grandes arcos de medio punto ejecutados en sólida cantería de granito provistos de potentes tajamares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08012','iglesia','Iglesia de San Nicolás','Templo barroco del siglo XVIII conocido como la "Catedral de la Costa" que presenta una monumental fachada clasicista de sillería calcárea con portalada esculpida, planta de tres naves y un robusto campanario octogonal de remate balaustrado que domina el núcleo urbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08012','iglesia','Antiguo Hospital e Iglesia de San Cristóbal','Complejo asistencial fundado en el siglo XV del que se conserva su','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08012','monumento','Ayuntamiento de Malgrat de Mar','Edificio consistorial modernista inaugurado en 1913 que destaca por su fachada decorada con azulejos cerámicos polícromos, balconadas de forja artística y un remate perimetral almenado de inspiración neogótica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08012','monumento','Torre de l''Esquena','Casa señorial de estilo modernista proyectada a finales del siglo XIX que exhibe ventanas de arco apuntado, ornamentación esgrafiada de motivos vegetales en paramentos exteriores y una torre mirador octogonal con cubierta piramidal cerámica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08136','monumento','Castillo de San Miguel (Castell de Sant Miquel)','Fortaleza medieval del siglo XII emplazada estratégicamente sobre la cordillera Litoral de la que subsisten la mitad de su imponente torre del homenaje cilíndrica de mampostería regular, tramos de la muralla perimetral defensiva y los cimientos de la antigua capilla castrense.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08136','iglesia','Iglesia de San Sadurní de Montornès','Edificio religioso de origen medieval transformado en el siglo XVI bajo cánones góticos tardíos y renacentistas que destaca por su portada clasicista ornamentada con hornacina para el santo, sus robustos contrafuertes exteriores y una torre-campanario cuadrangular rematada con gárgolas esculpidas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08136','monumento','Masía de Can Xec','Gran explotación agropecuaria tradicional documentada desde el siglo XV que presenta una fachada principal de tres cuerpos con tejado a dos aguas, un monumental portal dovelado de arco de medio punto y ventanales renacentistas con dinteles moldurados de arenisca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08151','monumento','Núcleos de población de Oristà','El término municipal incluye los siguientes núcleos de población: La Torre de Oristà y El Raval de Sant Feliu.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08151','iglesia','Iglesia de San Andrés de Oristà','Templo parroquial de origen románico modificado en el barroco que alberga una excepcional cripta prerrománica del siglo X descubierta en 1969, la cual consta de tres naves divididas por columnas con capiteles rústicos que sostienen bóvedas de arista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08151','iglesia','Iglesia de San Nazario (Sant Nazari de Pernau)','Pequeña capilla románica del siglo XII que presenta una planta de nave única con bóveda de cañón apuntada, un ábside semicircular orientado a levante y una espadaña de dos ojos construida con aparejo tosco de piedra local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08151','monumento','Museo de Alfarería Catalana','Centro expositivo ubicado en el núcleo urbano que custodia una exhaustiva colección de piezas cerámicas tradicionales e industriales procedentes de todas las comarcas de Cataluña desde el siglo XVII hasta la actualidad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08016','monumento','Núcleos de población de Pineda de Mar','El término municipal incluye los siguientes núcleos de población: Sant Pere de Riu.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08016','monumento','Acueducto Romano de Pineda','Monumental infraestructura civil del siglo III d.C. construida con opus caementicium y paramentos de mampostería regular de la que se conservan cuatro arcadas completas sobre pilares de sección rectangular destinadas al transporte de agua hacia las villas costeras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08016','iglesia','Iglesia de Santa María de Pineda','Templo parroquial de origen románico transformado en el siglo XVI en estilo gótico tardío y fortificado para resistir las incursiones piratas, el cual exhibe una fachada con portalada clasicista decorada con hornacina y ventanas molduradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08016','monumento','Castillo de Montpalau','Ruinas de una fortaleza medieval del siglo XI emplazada en una colina del parque natural del Montnegre que conserva tramos de sus muros defensivos construidos en mampostería basta y la base de su torre de vigía cilíndrica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08016','iglesia','Iglesia de San Pedro de Río (Sant Pere de Riu)','Templo románico del siglo XII edificado en sillería regular que presenta una sola nave con bóveda de cañón, un ábside semicircular liso y un recio campanario de torre de planta cuadrangular adosado al muro septentrional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08167','iglesia','Iglesia de San Salvador de Polinyà','Templo parroquial románico consagrado en 1122 que destaca internacionalmente por haber albergado un soberbio ciclo de pinturas murales al fresco del siglo XII dedicadas a la Infancia de Jesús y la Maiestas Domini que hoy se custodian en el Museo Diocesano de Barcelona, conservando in situ su ábside semicircular lombardo y muros de sillería basta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08167','monumento','Masía de Can Marata','Antigua heredad rural documentada desde el Medievo que presenta una planta rectangular con tejado a dos aguas, un gran portal dovelado de medio punto del siglo XVI y ventanas de cantería con dinteles renacentistas protegidos por repisas molduradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08184','palacio','Castillo-Palacio de Rubí','Fortaleza medieval documentada desde el siglo X y reedificada en el siglo XIV como residencia señorial gótica que muestra una planta rectangular estructurada alrededor de un patio de armas central con muros de mampostería regular, ventanas de tracería calada y portales dovelados de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08184','iglesia','Iglesia de San Pedro de Rubí','Templo parroquial de origen románico profundamente reformado en el siglo XVI bajo cánones góticos tardíos que exhibe una fachada occidental con un gran rosetón de tracería geométrica, contrafuertes exteriores exentos y un campanario de torre cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08184','monumento','Celler Cooperatiu de Rubí','Edificio de la arquitectura agraria modernista proyectado por el arquitecto Cèsar Martinell en 1920 que destaca por su innovadora estructura de arcos parabólicos de ladrillo visto, naves diáfanas ventiladas y grandes cubas de fermentación vinícola sustentadas sobre pilares de hormigón aligerado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08190','monumento','Núcleos de población de Saldes','El término municipal incluye los siguientes núcleos de población: Maçaners y L''Espà.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08190','monumento','Castillo de Saldes','Ruinas de una estratégica fortaleza medieval del siglo XI emplazada a los pies del macizo del Pedraforca de las que subsisten tramos notables de la muralla perimetral defensiva, los cimientos de la torre del homenaje y la capilla románica de Santa María con ábside semicircular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08190','iglesia','Iglesia de San Martín de Saldes','Templo de origen románico profundamente transformado en el siglo XVII bajo cánones barrocos que exhibe una fachada muy sobria con porche cubierto tradicional, muros exteriores de mampostería basta de piedra de alta montaña y una recia torre-campanario cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08190','iglesia','Santuario de Gresolet','Ermita rural documentada desde el siglo XIII situada en un profundo valle boscoso que presenta una tipología de nave única con bóveda de cañón apuntada, un ábside liso y dependencias anexas destinadas antiguamente a la acogida de pastores y peregrinos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90678','iglesia','Iglesia de San Balandrán (Sant Baldiri)','Templo parroquial de factura barroca edificado en el siglo XVIII sobre un oratorio medieval que destaca por albergar la tumba del histórico conseller en cap Rafael Casanova, presentando una fachada monumental de sillería vista y un robusto campanario octogonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90678','monumento','Termas Romanas de Sant Boi','Complejo termal del siglo II d.C. que constituye uno de los monumentos de época imperial mejor conservados de Cataluña al mantener intactas las estructuras del caldarium, frigidarium y tepidarium con sus sistemas de calefacción por hipocausto subterráneo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90678','monumento','Torre de Benviure','Torre de defensa medieval de planta circular construida en el siglo X mediante aparejo de mampostería regular con mortero de cal que servía para vigilar el paso estratégico del río Llobregat frente a las incursiones militares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90678','monumento','Can Torrents','Mansión señorial de origen gótico con reformas renacentistas de los siglos XVI y XVII que funciona como museo municipal, caracterizada por sus ventanas conopiales caladas, portal dovelado de medio punto y un patio central porticado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08222','monumento','Núcleos de población de Sant Llorenç d''Hortons','El término municipal incluye los siguientes núcleos de población: La Pedrera, San Juan Samora y El Grandet.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08222','iglesia','Iglesia de San Juan Samora','Templo románico del siglo XII edificado en sillería regular que consta de una sola nave cubierta por bóveda de cañón apuntada, un ábside semicircular orientado a levante con cornisa de canecillos lisos y una espadaña de dos vanos sobre la fachada de poniente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08222','iglesia','Iglesia de San Lorenzo d''Hortons','Edificio religioso de época barroca (siglo XVIII) construido con aparejo de mampostería enlucida que muestra una amplia nave longitudinal, una portalada de líneas clasicistas de cantería moldurada y una esbelta torre-campanario que domina el núcleo urbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08222','monumento','Masía de Can Muç','Gran explotación vitivinícola tradicional del Penedès estructurada a partir del siglo XVI que presenta un monumental portal dovelado de arco de medio punto en piedra caliza, ventanas con dinteles renacentistas labrados y amplias bodegas subterráneas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08224','monumento','Núcleos de población de Sant Martí de Centelles','El término municipal incluye los siguientes núcleos de población: Valldaneu y San Miguel de las Iglesias.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08224','monumento','Castillo de Centelles (Castell de Sant Martí)','Monumental fortaleza medieval del siglo IX situada sobre un espectacular risco rocoso que conserva gran parte de su recinto amurallado de sillería caliza regular, el portal de acceso gótico flanqueado por torres defensivas y las estancias residenciales del palacio de los barones.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08224','iglesia','Iglesia de San Martín de Centelles','Edificio religioso de origen románico profundamente transformado en el siglo XVIII en estilo barroco que exhibe una fachada de sillería enlucida con portalada clasicista, contrafuertes exteriores y una recia torre-campanario octogonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08224','iglesia','Iglesia de San Pedro de Valldaneu','Templo románico del siglo XII modificado en época barroca que presenta un ábside semicircular liso orientado a levante, una portada meridional de arco de medio punto y un campanario de espadaña de dos vanos ejecutado con aparejo tosco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90679','iglesia','Iglesia de San Martín de Sesgueioles','Monumental templo parroquial barroco construido en el siglo XVIII que exhibe una fachada de sillería de piedra arenisca local de líneas clasicistas sobrias, un interior de nave única con capillas intercomunicadas y un esbelto campanario octogonal con remate balaustrado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90679','monumento','La Torre del Reloj (Antiguo Campanario)','Estructura exenta del siglo XVI que formaba parte del primitivo templo de la villa de la que subsiste su torre cuadrangular de mampostería regular, reformada en centurias posteriores para albergar el mecanismo del reloj público y un armazón de hierro forjado artístico para las campanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08233','monumento','Núcleos de población de Sant Pere de Torelló','El término municipal incluye los siguientes núcleos de población: Sant Andreu de la Vola.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08233','iglesia','Santuario de Nuestra Señora de Bellmunt','Templo mariano emplazado de forma espectacular sobre un risco escarpado a más de mil metros de altitud cuyos orígenes se remontan al siglo XI, el cual presenta una estructura del siglo XVIII de mampostería basta adaptada al clima de alta montaña y una hospedería anexa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08233','iglesia','Iglesia de San Pedro','Monumental templo barroco edificado en el siglo XVIII por la saga de arquitectos Morató que destaca por su fachada de sillería de piedra arenisca local con portada neoclásica moldurada, un amplio interior de tres naves y una esbelta torre-campanario que corona el término.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08233','monumento','Puente de la Riera (Pont de la Riera)','Viaducto románico del siglo XII construido en cantería regular para salvar el curso del río Ges mediante un único arco de medio punto de gran luz reforzado con tajamares sobre la roca viva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90680','monumento','Núcleos de población de Sant Salvador de Guardiola','El término municipal incluye los siguientes núcleos de población: Salelles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90680','iglesia','Iglesia de San Salvador de Guardiola','Templo parroquial de origen románico transformado íntegramente en el siglo XVII en estilo barroco rural que presenta una fachada enlucida con portal de cantería moldurada, una nave diáfana con capillas laterales y una robusta torre-campanario de planta cuadrangular ejecutada en piedra caliza local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90680','iglesia','Iglesia de San Sadurní de Salelles','Edificio religioso románico del siglo XII edificado en sillería regular que presenta una sola nave cubierta por bóveda de cañón apuntada, un ábside semicircular orientado al este con cornisa de canecillos lisos y una espadaña de dos vanos sobre la fachada de poniente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08282','ermita','Ermita de la Virgen de la Alegría','Templo de origen románico profundamente modificado en el siglo XVIII en estilo barroco rural que destaca por su esbelto campanario de torre de planta cuadrada con ventanas geminadas de medio punto y por su fachada de paramentos enlucidos con un gran reloj de sol esgrafiado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08282','monumento','Masía de Can Reon','Gran heredad agrícola fortificada estructurada a partir del siglo XVI mediante muros de mampostería basta que presenta un monumental portal dovelado de arco de medio punto en granito local, ventanas con dinteles renacentistas labrados y amplias bodegas destinadas a la producción vinícola tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08282','monumento','Observatorio Astronómico de Tiana','Edificio científico e historicista construido a principios del siglo XX que combina una base de muros portantes de ladrillo visto con una gran cúpula metálica móvil para el albergue de instrumental óptico de precisión, integrado en un frondoso parque urbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08294','monumento','Dolmen de la Piedra Gentil (Dolmen de la Pedra Gentil)','Monumental sepulcro megalítico del Neolítico final emplazado dentro del parque natural del Montnegre que conserva su cámara funeraria delimitada por siete grandes bloques de piedra granítica hincados verticalmente y cubiertos por una colosal losa superior de forma elíptica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08294','iglesia','Iglesia Vieja de San Andrés','Ruinas consolidadas de un templo parroquial de origen románico profundamente modificado en el siglo XVIII que conservan alzados notables de sus muros de mampostería regular, la base del antiguo ábside y la estructura de su torre-campanario de planta cuadrangular integrada en el paisaje boscoso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08294','monumento','Masía de Can Pradell de la Serra','Antigua heredad rural de montaña fortificada y documentada desde el Medievo que destaca por su estructura tradicional de tres cuerpos con muros de mampostería regular, un gran portal dovelado de arco de medio punto en piedra granítica y ventanas renacentistas labradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90681','iglesia','Iglesia de Santa María de Agullana','Excepcional templo románico de finales del siglo XII edificado en sillería regular de granito que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular decorado exteriormente con un friso de arcuaciones lombardas y una majestuosa torrecampanario de sillería basta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90681','monumento','Necrópolis de Can Caderot','Yacimiento arqueológico de la Edad del Bronce final y de la Primera Edad del Hierro que conserva numerosas tumbas de incineración en urna, rodeadas por círculos de piedras toscas que atestiguan el temprano poblamiento de la comarca del Alt Empordà.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90681','monumento','Asilo Gomis','Edificio de estética modernista construido a principios del siglo XX por el arquitecto Josep Azemar i Pont que destaca por su fachada de ladrillo visto combinado con mampostería, ventanales de arcos parabólicos y detalles de cerámica vidriada polícroma.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17034','monumento','Núcleos de población de Calonge','El término municipal incluye los siguientes núcleos de población: Calonge y Sant Antoni de Calonge.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17034','monumento','Castillo de Calonge','Monumental fortaleza medieval del siglo XI reconstruida como residencia señorial gótica en el siglo XV que destaca por sus potentes murallas de sillería caliza, su torre del homenaje de planta cuadrada y un gran patio de armas con arcadas rebajadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17034','iglesia','Iglesia de San Martín de Calonge','Templo parroquial de estilo barroco clasicista edificado en el siglo XVIII que exhibe una fachada monumental de sillería vista con portada moldurada flanqueada por pilastras, una nave de gran amplitud y un esbelto campanario octogonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17034','monumento','Yacimiento Romano de Rufo (Vil·la romana de Collet)','Restos arqueológicos de una explotación agrícola y alfarera de época imperial que conserva las plantas de piedra de sus estancias productivas y hornos destinados a la fabricación de ánforas vinícolas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17220','iglesia','Iglesia de San Martín de Viladrau','Templo de origen románico profundamente transformado en el siglo XVIII en estilo barroco de aire clasicista que conserva de su fábrica del siglo XII los muros perimetrales de mampostería y un campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17220','monumento','Masía de La Sala','Gran heredad de montaña fortificada y documentada desde el Medievo que destaca por integrar en su estructura residencial una esbelta torre de defensa cilíndrica de mampostería basta destinada a la protección de los colonos contra el bandolerismo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25061','monumento','Núcleos de población de Cabó','El término municipal incluye los siguientes núcleos de población: El Vilar de Cabó y Organyà.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25061','iglesia','Iglesia de San Serni de Cabó','Templo románico del siglo XII edificado en sillería caliza regular que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular orientado a levante decorado exteriormente con cornisa de canecillos lisos y una espadaña de dos ojos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25078','iglesia','Iglesia de San Jaime','Templo parroquial levantado en el siglo XVIII en estilo barroco clasicista que cuenta con una amplia nave longitudinal, una fachada principal de sillería vista con un gran óculo central moldurado y un recio campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25098','monumento','Núcleos de población de Gavet de la Conca','El término municipal incluye los siguientes núcleos de población: Sant Salvador de Toló, Aransís y Sant Serni.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25098','iglesia','Iglesia de San Pere de Aransís','Templo románico del siglo XII edificado con sillería de piedra calcárea regular que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular orientado al este con decoración exterior de estilo lombardo y un robusto campanario adosado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25098','monumento','Castillo de Sant Gervàs','Ruinas consolidadas de una estratégica fortaleza defensiva militar del siglo XI de la que subsisten la gran torre del homenaje de planta circular de mampostería basta y tramos de cortina defensiva almenada asentados directamente sobre la roca viva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25098','iglesia','Iglesia de Sant Salvador de Toló','Edificio religioso de origen medieval transformado en el barroco rural que presenta una planta de nave única, una portalada con dovelas de piedra arenisca y un campanario de torre de planta cuadrangular que corona el perfil urbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25115','monumento','Núcleos de población de Isona i Conca Dellà','El término municipal incluye los siguientes núcleos de población: Isona, Conques, Figuerola d''Orcau, Sant Romà d''Abella y Orcau.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25115','monumento','Muralla Romana de Isona (Aeso)','Vestigios del sistema defensivo de época imperial del siglo II a.C. del que subsisten tramos notables de lienzos ejecutados con grandes bloques de piedra caliza escuadrada provistos de torres de defensa cuadrangulares angulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25115','iglesia','Castillo e Iglesia de Santa María de Orcau','Conjunto fortificado medieval del siglo XI emplazado de forma escarpada en la cumbre del cerro que conserva lienzos de muralla, los cimientos de la gran torre del homenaje de planta circular y la capilla románica con ábside semicircular decorado exteriormente con un friso de estilo lombardo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25115','iglesia','Iglesia de Santa María de Conques','Edificio religioso románico del siglo XII modificado en época barroca que muestra una planta de nave única con capillas laterales entre contrafuertes robustos, una portada meridional de tres arquivoltas en degradación y un campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25115','monumento','Yacimiento de Orcau (Dinosaurios de la Conca Dellà)','Espectacular paraje paleontológico musealizado del Cretácico Superior que conserva miles de huellas e icnitas impresas sobre una pared vertical de roca caliza que formaba parte de un antiguo ecosistema de humedales marinos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25179','monumento','Núcleos de población de Prullans','El término municipal incluye los siguientes núcleos de población: Ameller.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25179','iglesia','Iglesia de San Esteban de Prullans','Templo románico del siglo XII edificado en sillería regular de granito que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular orientado al este con cornisa de canecillos lisos y una portada meridional moldurada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25905','monumento','Núcleos de población de Ribera d''Ondara','El término municipal incluye los siguientes núcleos de población: Sant Antolí, Llindà, Briançó y Montlleó.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25905','monumento','Castillo y Núcleo Medieval de Montlleó','Ruinas de una estratégica fortificación del siglo XI de las que subsiste una imponente torre del homenaje de planta cuadrangular ejecutada con aparejo regular de grandes bloques de piedra caliza cementados con cal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25194','monumento','Núcleos de población de Sant Ramon','El término municipal incluye los siguientes núcleos de población: Portell, Gospí y Viver de Segarra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25194','iglesia','Santuario de San Ramón Nonato','Monumental e impresionante complejo conventual de la orden de la Merced edificado en el siglo XVIII conocido como "El Escorial de la Segarra" debido a sus dimensiones, el cual destaca por su fastuosa iglesia barroca con una fachada retablo de sillería caliza profusamente esculpida y un gran claustro neoclásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25202','monumento','Núcleos de población de Senterada','El término municipal incluye los siguientes núcleos de población: Burguet y Cérvoles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25202','monumento','Dolmen de la Casa del Moro','Destacado monumento megalítico del Neolítico final emplazado en la comarca del Pallars Jussà que conserva su cámara funeraria delimitada por grandes losas de piedra local hincadas verticalmente en el terreno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25216','monumento','Núcleos de población de Talavera','El término municipal incluye los siguientes núcleos de población: Pallerols, Civit y Bellmunt de Segarra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25216','iglesia','Iglesia de San Jaime de Pallerols','Edificio religioso románico del siglo XII edificado en cantería regular que presenta una sola nave con bóveda de cañón, un ábside semicircular orientado al este con cornisa de canecillos lisos y un campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25233','iglesia','Iglesia de San Juan Bautista','Templo parroquial levantado en el siglo XVIII en estilo barroco clasicista que cuenta con una amplia nave longitudinal, una fachada principal de sillería vista con un gran óculo central moldurado y un recio campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25244','iglesia','Iglesia de Santa María de Vilagrassa','Templo parroquial de origen románico profundamente transformado en época barroca que conserva de su fábrica del siglo XII una espectacular portada meridional de múltiples arquivoltas molduradas esculpidas con motivos geométricos por la escuela de Lleida y un esbelto campanario inclinado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25248','iglesia','Iglesia de San Pedro','Templo parroquial de factura neoclásica del siglo XVIII construido sobre un oratorio medieval anterior que presenta una amplia nave con capillas laterales, una fachada de paramentos enlucidos con portalada de piedra caliza moldurada y un robusto campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38029','iglesia','Iglesia de San Mauro Abad (San Mauro el Viejo)','Templo románico de transición y mudéjar edificado en sillería de alta montaña en el siglo XVI que consta de una sola nave con bóveda de madera labrada, un ábside semicircular orientado al este con cornisa de canecillos lisos y una espadaña de dos vanos sobre la fachada de poniente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90682','monumento','Núcleos de población de Allande','El término municipal incluye los siguientes núcleos de población: Pola de Allande, Berducedo y San Emiliano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90682','palacio','Palacio de Cienfuegos de Peñalba','Monumental palacio señorial erigido en el siglo XIV sobre una colina que domina la villa y remodelado en el siglo XVI bajo cánones renacentistas, caracterizado por sus tres recias torres cuadrangulares de sillería de pizarra rústica, su patio de armas central columnado y un aspecto de imponente fortaleza defensiva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90682','iglesia','Iglesia de San Andrés de Pola de Allande','Templo de estilo gótico tardío del siglo XVI que presenta una amplia nave con bóvedas de crucería estrellada, una portada con arquivoltas apuntadas de piedra arenisca local y un robusto espadaña exenta de tres vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90682','monumento','Castro de San Chuis','Yacimiento arqueológico musealizado del periodo castreño y de la época romana que conserva las plantas completas de piedra de sus viviendas circulares y rectangulares, rodeadas por una potente muralla defensiva perimetral.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05005','monumento','Núcleos de población de Cangas de Onís','El término municipal incluye los siguientes núcleos de población: Covadonga y Corao.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05005','monumento','Puente Romano de Cangas de Onís','Monumental e imponente infraestructura civil de origen medieval (siglo XIV) que salva el cauce del río Sella mediante un colosal arco apuntado central flanqueado por dos arcos de descarga menores, del cual cuelga una réplica de la Cruz de la Victoria.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05005','iglesia','Santuario y Santa Cueva de Covadonga','Magna basílica neorrománica de finales del siglo XIX tallada en sillería caliza rosada que contrasta con el santuario troglodítico excavado en una balma natural sobre una colosal cascada de agua, donde se halla la tumba del rey Don Pelayo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05005','iglesia','Aula Arqueológica de la Iglesia de la Santa Cruz','Capilla reedificada sobre un dolmen megalítico prehistórico del año 3000 a.C. y posterior iglesia del siglo VIII mandada construir por el rey Favila, de la que se conserva la cámara funeraria del túmulo subterráneo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90010','iglesia','Iglesia de Nuestra Señora de la Consolación','Templo parroquial levantado en el siglo XVIII en estilo barroco rural que cuenta con una amplia nave longitudinal, una fachada principal enlucida con un portal de cantería moldurada y un campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07008','iglesia','Santuario de San Salvador (Santuari de Sant Salvador)','Monumental complejo religioso fortificado emplazado de forma espectacular en la cumbre del cerro homónimo a más de quinientos metros de altitud, el cual presenta una iglesia barroca del siglo XVIII con fachada de sillería caliza vista y un interior de gran solemnidad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07008','monumento','Castillo de Santueri','Ruinas de una mítica e imponente fortaleza militar medieval del siglo XIV erigida sobre un escarpado peñón rocoso calcáreo, de la que subsisten potentes lienzos de murallas almenadas construidos con aparejo regular y tres robustas torres de defensa angulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07008','iglesia','Iglesia de San Miguel','Magna iglesia de traza gótica tardía iniciada en el siglo XVI que presenta una imponente nave única de gran anchura, capillas laterales entre contrafuertes robustos provistas de ventanales calados y una fastuosa fachada occidental barroca de sillería calada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07056','iglesia','Claustro del Convento de San Francisco (Sant Francesc)','Cenobio franciscano fundado en el siglo XVII de estilo barroco que destaca por su bellísimo claustro de líneas clásicas muy sobrias ejecutado en cantería perfecta de piedra caliza, caracterizado por sus alas de galerías porticadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24002','monumento','Fortaleza de la Mota','Imponente conjunto monumental fortificado de origen medieval (siglos XI-XIV) que corona el cerro de la Mota, con recinto amurallado, alcazaba e iglesia mayor abacial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24002','palacio','Palacio Abacial','Edificio civil de estilo neoclásico (siglo XVIII), sede histórica de los abades de la ciudad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24010','catedral','Catedral de la Natividad de Nuestra Señora','Catedral renacentista (siglo XVI) levantada sobre la antigua mezquita, vinculada a Andrés de Vandelvira; conjunto declarado Patrimonio de la Humanidad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24010','palacio','Palacio de Jabalquinto','Palacio de espectacular fachada gótico-isabelina flamígera (siglo XV) con patio renacentista, una de las joyas civiles de la ciudad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24010','monumento','Plaza de los Leones (del Pópulo)','Conjunto monumental renacentista con la Fuente de los Leones y la Casa del Pópulo, en el centro histórico Patrimonio de la Humanidad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19044','monumento','Castillo de Atienza','Castillo roquero medieval encaramado en un espolón calcáreo, con torre del homenaje, que dominaba la frontera del Reino de Castilla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19044','iglesia','Iglesias románicas de Atienza','Notable conjunto de iglesias románicas de los siglos XII-XIII, entre ellas San Bartolomé, testimonio del esplendor medieval de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19053','monumento','Castillo de la Peña Bermeja','Fortaleza medieval (siglos XII-XV) sobre un cerro rojizo, con recinto amurallado y jardín histórico, vinculada a los arzobispos de Toledo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19053','monumento','Recinto Amurallado de Brihuega','Murallas medievales que conservan varias puertas históricas en torno al casco antiguo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19053','monumento','Real Fábrica de Paños','Edificio industrial neoclásico de planta circular (siglo XVIII) erigido bajo Carlos III para la manufactura textil.','inventario_monumentos_pdf');
